import { t, ui, locale, bindText, onLanguageChange } from './i18n.js';
import { resultInsightsHTML } from './result-insights.js';
const html=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=value=>Number.isFinite(value)?new Intl.NumberFormat(locale()).format(value):t('Non disponibile');
const date=value=>{const d=new Date(value);return value&&Number.isFinite(d.getTime())?new Intl.DateTimeFormat(locale(),{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}).format(d):'—';};
const duration=value=>Number.isFinite(value)?value<60000?`${Math.round(value/1000)} s`:`${new Intl.NumberFormat(locale(),{maximumFractionDigits:1}).format(value/60000)} min`:t('Non disponibile');
const help=(label,text)=>ui`<details class="governance-help"><summary aria-label="Aiuto: ${html(label)}">?</summary><p>${html(text)}</p></details>`;

export function createGovernancePanel({host,settingsHost,toast=()=>{},onSettingsChange=()=>{}}={}) {
  let snapshot=null,context={tasks:[],runs:[],workflows:[]},visible=false,settingsVisible=false,loading=false,saving=false,busy=false,error='',settingsDirty=false,disposed=false,version=0;
  let outcomeTarget=null,insightView='projects',loadingScope=null;
  const insightScope=()=>context.filter==='all'?null:context.scopeId||null;
  const dialog=document.createElement('dialog');dialog.id='outcome-dialog';dialog.className='ops-dialog';dialog.setAttribute('aria-labelledby','outcome-title');document.body.append(dialog);
  function allowed(){return !busy&&!loading&&!saving&&!disposed;}
  function locks(){host.querySelectorAll('[data-governance-mutation]').forEach(el=>el.disabled=!allowed());settingsHost.querySelectorAll('[data-governance-mutation]').forEach(el=>el.disabled=!allowed());dialog.querySelectorAll('button[type="submit"]').forEach(el=>el.disabled=!allowed());}
  async function request(body){if(disposed)throw Error(t('Sessione scaduta.'));const response=await fetch(`/api/governance${!body&&insightScope()?`?scopeId=${encodeURIComponent(insightScope())}`:''}`,body?{method:'POST',headers:{'Content-Type':'application/json','X-Fuori-Studio':'local'},body:JSON.stringify(body)}:{cache:'no-store'});let value;try{value=await response.json();}catch{throw Error(t('I dati di utilizzo non sono disponibili.'));}if(disposed)throw Error(t('Sessione scaduta.'));if(!response.ok){const e=Error(value.error||t('Operazione non riuscita.'));e.status=response.status;throw e;}return value;}
  function accept(value){if(!value?.settings||!value.daily||!value.usageTotals)throw Error(t('I dati di utilizzo non sono validi.'));snapshot=value;error='';render();renderSettings();onSettingsChange(value.settings);if(visible&&snapshot.insights&&snapshot.insights.scopeId!==insightScope())void load();}
  async function load(){const scope=insightScope();if(disposed||loading&&loadingScope===scope)return;const current=++version;loadingScope=scope;loading=true;error='';render();locks();try{const value=await request();if(current!==version)return;loading=false;accept(value);}catch(e){if(current!==version)return;loading=false;error=e.message;render();renderSettings();}finally{locks();}}
  function metric(label,value,detail,kind=''){return ui`<article class="governance-metric ${kind}"><span>${html(label)}</span><strong>${html(value)}</strong><p>${html(detail)}</p></article>`;}
  function eligibleTargets(){return [...context.tasks.filter(item=>(!insightScope()||item.scopeId===insightScope())&&item.status==='completed'&&item.artifacts?.at(-1)?.decision==='approved').map(item=>({taskId:item.id,title:item.title,kind:t('Incarico')})),...context.runs.filter(item=>(!insightScope()||item.scopeId===insightScope())&&item.status==='completed'&&item.decision?.status==='approved').map(item=>({runId:item.id,title:item.title,kind:t('Patch')}))];}
  function outcomeFor(target){return snapshot?.outcomes?.find(item=>target.taskId?item.taskId===target.taskId:item.runId===target.runId);}
  function render(){if(!visible)return;if(!snapshot){host.innerHTML=error?ui`<p class="ops-error">${html(error)}</p><button type="button" class="ops-button" data-governance-action="refresh">Riprova</button>`:ui('<p class="governance-notice" role="status">Caricamento dei risultati…</p>');return;}
    const {daily,usageTotals:usage,feedback={},metrics={},period={}}=snapshot,deliveries=metrics.deliveries||{},cycles=metrics.cycles||{},targets=eligibleTargets();
    host.innerHTML=ui`<div class="governance-heading"><div><h3>Il valore del lavoro, misurato.</h3><p>Risultati e utilizzo di questa installazione, in tutti gli ambiti. Il tempo risparmiato viene dalle tue valutazioni.</p></div><button type="button" class="ops-button" data-governance-action="refresh"${loading?' disabled':''}>${loading?t('Aggiornamento…'):t('Aggiorna dati')}</button></div>${error?ui`<p class="ops-error" role="alert">${html(error)}</p>`:''}<div class="governance-grid">${metric(t('Chiamate AI oggi'),number(daily.calls),ui`${number(daily.remaining)} ancora consentite · reset ${date(period.resetAt)} (giorno UTC)`)}${metric(t('Consegne approvate'),number(deliveries.accepted),ui`${number(deliveries.reviewed)} valutate · ${Number.isFinite(deliveries.acceptanceRatio)?ui`${Math.round(deliveries.acceptanceRatio*100)}% approvate`:t('Percentuale non disponibile')}`)}${metric(t('Tempo medio alla consegna'),duration(cycles.averageMs),ui`${number(cycles.count)} cicli osservati · durata trascorsa, non tempo risparmiato`)}${metric(t('Utilità dichiarata'),ui`${number(feedback.helpful)} utili`,ui`${number(feedback.responses)} valutazioni · ${number(feedback.unhelpful)} non utili`)}${metric(t('Minuti risparmiati dichiarati'),number(feedback.minutesSaved),ui`${number(feedback.minutesSavedEntries)} stime inserite da te`)}${metric(t('Problemi attuali'),number(metrics.failures?.current),ui`${number(metrics.failures?.events)} eventi di errore registrati`)}</div><section class="governance-section"><div class="governance-title-row"><h3>Consumo osservato</h3>${help(t('Chiamate e token'),t('Il limite conta le chiamate AI, non gli euro. I token sono solo quelli restituiti dai servizi. Valori mancanti non equivalgono a zero e il conteggio può essere parziale. Questo pannello non stima costi monetari.'))}</div><div class="governance-usage"><div><span>Token in ingresso</span><strong>${number(usage.inputTokens)}</strong><small>${usage.unknownInputCount?ui`${number(usage.unknownInputCount)} chiamate senza dato · parziale`:t('Dati riportati dai servizi')}</small></div><div><span>Token in uscita</span><strong>${number(usage.outputTokens)}</strong><small>${usage.unknownOutputCount?ui`${number(usage.unknownOutputCount)} chiamate senza dato · parziale`:t('Dati riportati dai servizi')}</small></div><div><span>Chiamate registrate</span><strong>${number(usage.calls)}</strong><small>${number(usage.succeeded)} riuscite · ${number(usage.failed)} fallite · ${number(usage.running)} in corso</small></div></div><p class="governance-caption">Annullate: ${number(usage.cancelled)} · Tempo scaduto: ${number(usage.timedOut)} · Interrotte: ${number(usage.interrupted)}. Le chiamate non corrispondono a un importo in denaro.</p></section>${resultInsightsHTML(snapshot.insights,{scopeId:insightScope(),view:insightView,failed:Boolean(error)})}<section class="governance-section"><div class="governance-title-row"><h3>È stato utile?</h3>${help(t('La tua valutazione'),t('Una consegna approvata può essere utile o poco utile. Registra il tuo giudizio e, facoltativamente, una stima del tempo risparmiato. Lo studio non la deduce dai token o dalla durata del lavoro.'))}</div>${targets.length?ui`<div class="governance-outcomes">${targets.slice().reverse().slice(0,20).map(target=>{const outcome=outcomeFor(target);return ui`<article><div><small>${target.kind}</small><strong>${html(target.title)}</strong><p>${outcome?`${outcome.helpful?t('Utile'):t('Non utile')}${Number.isFinite(outcome.minutesSaved)?ui` · ${number(outcome.minutesSaved)} min dichiarati`:''}`:t('Nessuna valutazione ancora')}</p></div><button type="button" class="ops-button" data-governance-action="outcome" data-kind="${target.taskId?'task':'run'}" data-id="${html(target.taskId||target.runId)}" data-governance-mutation>${outcome?t('Modifica valutazione'):t('Valuta risultato')}</button></article>`;}).join('')}</div>`:ui('<p class="governance-empty">Dopo aver approvato una consegna o una patch, potrai valutarne l’utilità qui.</p>')}</section>`;locks();
  }
  function renderSettings(){if(!settingsVisible||settingsDirty)return;if(!snapshot){settingsHost.innerHTML=error?ui`<p class="ops-error">${html(error)}</p><button type="button" class="ops-button" data-governance-action="refresh">Carica i limiti</button>`:ui('<p class="governance-notice">Caricamento dei limiti…</p>');return;}
    const settings=snapshot.settings;settingsHost.innerHTML=ui`<section class="governance-settings"><div class="governance-title-row"><h3>Quanto può lavorare lo studio</h3>${help(t('Limiti e autonomia'),t('I limiti si applicano alle nuove chiamate AI di questa installazione. Un limite di zero blocca nuovi avvii. Attivare le routine autonome autorizza chiamate AI senza conferma a ogni esecuzione: scegli un limite giornaliero esplicito.'))}</div><p class="governance-caption">Limiti reali del server. Giorno ${html(snapshot.period?.day||'UTC')} · ${number(snapshot.daily.calls)} chiamate usate · massimo ${number(snapshot.limits?.maxConcurrentCalls)} chiamate contemporanee.</p><form id="governance-settings-form"><div class="ops-form-grid"><div class="ops-field"><label for="governance-call-limit">Chiamate AI al giorno</label><input id="governance-call-limit" name="dailyCallLimit" type="number" min="0" max="1000" step="1" value="${settings.dailyCallLimit}" required><p class="ops-hint">Un conteggio di chiamate, non un budget in euro. 0 blocca nuovi avvii.</p></div><div class="ops-field"><label for="governance-call-seconds">Durata massima di una chiamata · secondi</label><input id="governance-call-seconds" name="maxCallSeconds" type="number" min="1" max="1800" step="1" value="${settings.maxCallSeconds}" required><p class="ops-hint">Alla scadenza il server interrompe la chiamata.</p></div></div><label class="ops-check governance-autonomy"><input type="checkbox" name="autonomousRoutines"${settings.autonomousRoutines?' checked':''}><span>Autorizzo l’avvio automatico delle routine abilitate<small>Gli incarichi testuali creati dalle routine possono chiamare l’AI e generare consumo senza un mio avvio ogni volta. Repository, piani e altri incarichi mantengono l’avvio esplicito.</small></span></label><div class="ops-field governance-auto-limit"><label for="governance-auto-limit">Avvii autonomi al giorno</label><input id="governance-auto-limit" name="maxAutonomousRunsPerDay" type="number" min="0" max="100" step="1" value="${settings.maxAutonomousRunsPerDay}" required><p class="ops-hint">${number(snapshot.daily.autonomousRuns)} già avviati oggi · ${number(snapshot.daily.autonomousRemaining)} ancora consentiti. Il limite generale delle chiamate resta valido.</p></div><p class="governance-notice">${settings.autonomousRoutines?t('Le routine autonome sono attive. Disattiva la casella e salva per tornare agli avvii manuali.'):t('Le routine autonome sono disattivate. Finché non abiliti e salvi questa opzione, ogni incarico richiede il tuo avvio.')}</p><p class="ops-form-error" role="alert" hidden></p><div class="governance-settings-actions"><button type="button" class="ops-button" data-governance-action="discard-settings">Ricarica impostazioni</button><button type="submit" class="ops-button is-primary" data-governance-mutation>Salva limiti e autorizzazioni</button></div></form></section>`;
    const form=settingsHost.querySelector('form');form.addEventListener('input',()=>{settingsDirty=true;});form.addEventListener('submit',async event=>{event.preventDefault();if(!allowed()||!form.reportValidity())return;const data=new FormData(form),box=form.querySelector('.ops-form-error');saving=true;box.hidden=true;locks();try{const value=await request({action:'configure',payload:{expectedVersion:settings.version,dailyCallLimit:Number(data.get('dailyCallLimit')),maxCallSeconds:Number(data.get('maxCallSeconds')),autonomousRoutines:data.has('autonomousRoutines'),maxAutonomousRunsPerDay:Number(data.get('maxAutonomousRunsPerDay'))}});settingsDirty=false;saving=false;accept(value);toast(t('Limiti e autorizzazioni aggiornati.'));}catch(e){box.textContent=e.status===409?ui`${e.message} Ricarica le impostazioni prima di modificarle di nuovo.`:e.message;box.hidden=false;}finally{saving=false;locks();}});locks();
  }
  async function openOutcome(target){outcomeTarget=target;if(!allowed())return;if(!snapshot){await load();if(!snapshot)return;}const existing=outcomeFor(target);
    dialog.innerHTML=ui`<div class="ops-dialog-heading"><div><div class="eyebrow">IL VALORE DEL RISULTATO</div><h2 id="outcome-title">È stato utile?</h2></div><button type="button" class="ops-icon" data-outcome-close aria-label="Chiudi finestra">✕</button></div><form id="outcome-form"><div class="ops-form-body"><p class="ops-form-intro"><strong>${html(target.title)}</strong>. La valutazione è tua e puoi aggiornarla.</p><fieldset class="governance-rating"><legend>Questo risultato ti ha aiutato?</legend><label><input type="radio" name="helpful" value="yes" required${existing?.helpful===true?' checked':''}>Sì, utile</label><label><input type="radio" name="helpful" value="no" required${existing?.helpful===false?' checked':''}>No, poco utile</label></fieldset><div class="ops-field"><label for="outcome-minutes">Minuti risparmiati · facoltativo</label><input id="outcome-minutes" name="minutesSaved" type="number" min="0" max="10080" step="1" value="${Number.isFinite(existing?.minutesSaved)?existing.minutesSaved:''}"><p class="ops-hint">Una tua stima. Lascia vuoto se non sai valutarlo: non verrà contato come zero.</p></div><div class="ops-field"><label for="outcome-note">Cosa ha funzionato o mancava · facoltativo</label><textarea id="outcome-note" name="note" maxlength="2000" rows="4">${html(existing?.note||'')}</textarea></div><p class="ops-form-error" role="alert" hidden></p></div></form><div class="ops-dialog-footer"><button type="button" class="ops-button" data-outcome-close>Annulla</button><button type="submit" form="outcome-form" class="ops-button is-primary">Salva valutazione</button></div>`;if(!dialog.open)dialog.showModal();locks();
    dialog.querySelector('form').addEventListener('submit',async event=>{event.preventDefault();if(!allowed())return;const form=event.currentTarget;if(!form.reportValidity())return;const data=new FormData(form),box=form.querySelector('.ops-form-error');saving=true;box.hidden=true;locks();try{const value=await request({action:'saveOutcome',payload:{...(target.taskId?{taskId:target.taskId}:{runId:target.runId}),helpful:data.get('helpful')==='yes',...(data.get('minutesSaved')!==''?{minutesSaved:Number(data.get('minutesSaved'))}:{}),note:data.get('note').trim(),...(existing?{expectedVersion:existing.version}:{})}});accept(value);dialog.close();toast(t('Valutazione salvata. Le stime restano distinte dalle misure del server.'));}catch(e){box.textContent=e.message;box.hidden=false;}finally{saving=false;locks();}});
  }
  function click(event){const button=event.target.closest('[data-governance-action]');if(!button||button.disabled)return;const action=button.dataset.governanceAction;if(action==='insight-view'&&['projects','procedures'].includes(button.dataset.view)){insightView=button.dataset.view;render();host.querySelector(`[data-view="${insightView}"]`)?.focus();return;}if(action==='refresh'){void load();return;}if(action==='discard-settings'){settingsDirty=false;void load();return;}if(action==='outcome'){const item=eligibleTargets().find(target=>(button.dataset.kind==='task'?target.taskId:target.runId)===button.dataset.id);if(item)void openOutcome(item);}}
  const stopLanguage=onLanguageChange(()=>{if(disposed)return;render();if(saving)return;const dirty=settingsDirty;settingsDirty=false;renderSettings();settingsDirty=dirty;if(dialog.open&&outcomeTarget)void openOutcome(outcomeTarget);});
  host.addEventListener('click',click);settingsHost.addEventListener('click',click);dialog.addEventListener('click',event=>{if(event.target.closest('[data-outcome-close]')&&!saving)dialog.close();});dialog.addEventListener('cancel',event=>{if(saving)event.preventDefault();});
  function expire(){disposed=true;version++;if(dialog.open)dialog.close();}window.addEventListener('studio-session-expired',expire);
  return {load,openOutcome,setContext(value){const previous=insightScope();context={...context,...value};if(visible&&previous!==insightScope())void load();render();},setVisible({dashboard=false,settings=false}={}){const changed=dashboard&&!visible||settings&&!settingsVisible;visible=dashboard;settingsVisible=settings;host.hidden=!visible;settingsHost.hidden=!settingsVisible;render();renderSettings();if(changed&&!loading&&(dashboard||!settingsDirty))void load();},setBusy(value){busy=Boolean(value);locks();},getSettings:()=>snapshot?.settings,dispose(){stopLanguage();expire();window.removeEventListener('studio-session-expired',expire);host.removeEventListener('click',click);settingsHost.removeEventListener('click',click);dialog.remove();}};
}
